{
  "name": "@tokenmix/opencode-plugin",
  "version": "0.3.0",
  "description": "OpenCode plugin that adds tokenmix.ai account tools (top-up, model catalog, balance hints) and a chat session usage tracker.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "prepublishOnly": "pnpm build"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "tokenmix",
    "opencode",
    "opencode-plugin",
    "ai",
    "llm",
    "coding-agent"
  ],
  "license": "MIT",
  "homepage": "https://tokenmix.ai",
  "repository": {
    "type": "git",
    "url": "https://github.com/TokenMixAi/tokenmix-opencode-plugin.git"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.15.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.10",
    "@opencode-ai/sdk": "^1.15.10",
    "@types/node": "^22.9.0",
    "typescript": "^5.6.3",
    "vitest": "^4.1.7",
    "zod": "^4.1.8"
  },
  "pnpm": {
    "onlyBuiltDependencies": [
      "esbuild"
    ]
  }
}
